"use strict";(self.webpackChunksketch_blog=self.webpackChunksketch_blog||[]).push([[1861],{2912(e,a,t){t.r(a),t.d(a,{_pageData:()=>n,default:()=>h});var p=t(641);const n=JSON.parse('{"path":"/notes/%E4%B9%A6%E5%BD%B1%E9%9F%B3%E6%B8%B8/%E4%B9%A6%E7%B1%8D/%E5%B1%80%E5%A4%96%E4%BA%BA.html","title":"局外人","lang":"zh-CN","frontmatter":{"title":"局外人","date":"2023-04-17T00:00:00.000Z","tags":["读书"]},"git":{},"filePathRelative":"notes/书影音游/书籍/局外人.md"}'),r={name:"局外人.md"},h=(0,t(6262).A)(r,[["render",function(e,a,t,n,r,h){return(0,p.uX)(),(0,p.CE)("div",null,[...a[0]||(a[0]=[(0,p.Fv)('<h1 id="局外人" tabindex="-1"><a class="header-anchor" href="#局外人"><span>局外人</span></a></h1><p>主角参与母亲葬礼之后，结识了女友即其他几个朋友，散步期间与人冲突，开枪杀了人被捕入狱，开庭审判之后被执行死刑（好像没确定判罚）的故事。</p><h2 id="书名" tabindex="-1"><a class="header-anchor" href="#书名"><span>书名</span></a></h2><p>主角正如书名所写，是个没什么感情的、好像什么事都不关己的一个“局外人”</p><p>母亲去世不关心</p><p>女友问他爱不爱她，主角并不爱她，只是为了肉欲</p><p>开枪杀人，没有动机（只是因为对方先掏了刀？，加上天热，烦躁情况下开了枪）</p><p>开庭期间，看着律师、其他人和判官辩解，他做局外人..</p><p>主角并没有撒谎，只是依照事实陈述自己的事情</p><h2 id="这本书探讨的是什么" tabindex="-1"><a class="header-anchor" href="#这本书探讨的是什么"><span>这本书探讨的是什么</span></a></h2><p>探讨的好像是审判主角不以杀人的行为为根据，而是以主角冷漠的感情作为依据去处理这个案子。</p><p>具体想表达什么东西，看不懂..</p><blockquote><p><a href="https://www.zhihu.com/question/20348140/answer/679068214" target="_blank" rel="noopener noreferrer">(30 封私信 / 80 条消息) 《局外人》这本小说牛在哪里？为什么我看过以后很难总结出收获？ - 知乎 (zhihu.com)</a></p><p><a href="https://www.zhihu.com/question/376919438/answer/1179497453" target="_blank" rel="noopener noreferrer">(30 封私信 / 80 条消息) 最近在看加缪的局外人，快看完了，但是看不出来想表达什么，思考了一晚上，也没啥进展，有没有人解答下？ - 知乎 (zhihu.com)</a></p></blockquote>',13)])])}]])}}]);